#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/devicetree.h>

#include "ltc2959.h" /* For register definitions */

LOG_MODULE_REGISTER(ltc2959_emul, LOG_LEVEL_DBG);

#define DT_DRV_COMPAT adi_ltc2959

/* Max register address + 1 */
#define LTC2959_REG_MAX_ADDR (LTC2959_REG_ACCUM_CHARGE_LSB + 1)

/**
 * @brief Emulation data for the LTC2959 fuel gauge.
 */
struct ltc2959_emul_data {
	struct i2c_emul_api api;
	uint8_t reg[LTC2959_REG_MAX_ADDR]; /* Internal register map */
	uint8_t current_reg_addr; /* For combined messages */
	uint32_t rsense_milliohms;
};

static int ltc2959_emul_transfer_func(const struct emul *target, struct i2c_msg *msgs,
				      int num_msgs, int bytes_read, int bytes_write)
{
	struct ltc2959_emul_data *data = (struct ltc2959_emul_data *)target->data;
	int ret = 0;

	for (int i = 0; i < num_msgs; i++) {
		if (msgs[i].flags & I2C_MSG_WRITE) {
			if (msgs[i].len == 0) {
				LOG_WRN("I2C write message with 0 length");
				continue;
			}
			data->current_reg_addr = msgs[i].buf[0];
			if (data->current_reg_addr >= LTC2959_REG_MAX_ADDR) {
				LOG_ERR("Invalid register address 0x%02x for write",
					data->current_reg_addr);
				return -EIO;
			}
			for (int j = 1; j < msgs[i].len; j++) {
				if (data->current_reg_addr + j - 1 >= LTC2959_REG_MAX_ADDR) {
					LOG_ERR("Write beyond register map at 0x%02x",
						data->current_reg_addr + j - 1);
					return -EIO;
				}
				data->reg[data->current_reg_addr + j - 1] = msgs[i].buf[j];
				LOG_DBG("Write reg 0x%02x: 0x%02x",
					data->current_reg_addr + j - 1, msgs[i].buf[j]);
			}
		} else if (msgs[i].flags & I2C_MSG_READ) {
			if (data->current_reg_addr >= LTC2959_REG_MAX_ADDR) {
				LOG_ERR("Invalid register address 0x%02x for read",
					data->current_reg_addr);
				return -EIO;
			}
			for (int j = 0; j < msgs[i].len; j++) {
				if (data->current_reg_addr + j >= LTC2959_REG_MAX_ADDR) {
					LOG_ERR("Read beyond register map at 0x%02x",
						data->current_reg_addr + j);
					return -EIO;
				}
				msgs[i].buf[j] = data->reg[data->current_reg_addr + j];
				LOG_DBG("Read reg 0x%02x: 0x%02x",
					data->current_reg_addr + j, msgs[i].buf[j]);
			}
		} else {
			LOG_ERR("Unsupported I2C message flags 0x%x", msgs[i].flags);
			return -EIO;
		}
	}

	return ret;
}

static void ltc2959_emul_init(struct ltc2959_emul_data *data)
{
	/* Initialize all registers to 0 */
	(void)memset(data->reg, 0, sizeof(data->reg));

	/* Set initial status register to 0x01 as expected by test_get_props__returns_ok */
	data->reg[LTC2959_REG_STATUS] = 0x01;
}

/*
 * Device Tree nodes for adi,ltc2959 are expected to be children of an
 * i2c-emul-controller.
 */
#define LTC2959_EMUL_DEFINE(node_id)						\
	static struct ltc2959_emul_data ltc2959_emul_data_##node_id = {		\
		.rsense_milliohms = DT_PROP(node_id, rsense_milliohms),		\
	};									\
	static const struct i2c_emul_api ltc2959_emul_api_##node_id = {		\
		.transfer = ltc2959_emul_transfer_func,				\
	};									\
	EMUL_DEFINE(emul_##node_id, node_id, &ltc2959_emul_api_##node_id,	\
		    &ltc2959_emul_data_##node_id);				\
										\
	static int ltc2959_emul_init_##node_id(const struct device *dev)	\
	{									\
		ARG_UNUSED(dev);						\
		ltc2959_emul_init(&ltc2959_emul_data_##node_id);		\
		return 0;							\
	}									\
	SYS_INIT(ltc2959_emul_init_##node_id, POST_KERNEL,			\
		 CONFIG_APPLICATION_INIT_PRIORITY);

DT_FOREACH_STATUS_OKAY(DT_DRV_COMPAT, LTC2959_EMUL_DEFINE);
